using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_12d8c7899d2f43cfb34e2a650502fe8a.Client;

namespace sv_12d8c7899d2f43cfb34e2a650502fe8a.Auth;

/// <summary>
/// Subscribes to auth state changes and persists the user info via PersistentComponentState
/// so the WebAssembly runtime can pick it up after prerendering.
/// </summary>
public class PersistingAuthenticationStateProvider : IDisposable
{
    private readonly PersistentComponentState _state;
    private readonly AuthenticationStateProvider _authenticationStateProvider;
    private PersistingComponentStateSubscription _subscription;

    public PersistingAuthenticationStateProvider(
        PersistentComponentState persistentComponentState,
        AuthenticationStateProvider authenticationStateProvider)
    {
        _state = persistentComponentState;
        _authenticationStateProvider = authenticationStateProvider;

        _subscription = _state.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    private async Task OnPersistingAsync()
    {
        var authState = await _authenticationStateProvider.GetAuthenticationStateAsync();
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var email = principal.FindFirst(ClaimTypes.Email)?.Value
                        ?? principal.Identity.Name
                        ?? string.Empty;

            var roles = principal.FindAll(ClaimTypes.Role)
                .Select(c => c.Value)
                .ToArray();

            _state.PersistAsJson(nameof(UserInfo), new UserInfo
            {
                Email = email,
                Roles = roles
            });
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

